import { Kysely, PostgresDialect } from 'kysely';
import pg from 'pg';
import type { Env } from '../config.js';

/**
 * Database connection abstraction (SDD §11.7: connects as `haven_api` through
 * Supabase's pooler, port 6543, transaction mode).
 *
 * `Database` is an EMPTY placeholder — the real table interface is generated by
 * `kysely-codegen` from the schema once the migrations exist (docs/IMPLEMENTATION-PLAN.md
 * M1, step 1). Nothing in this bootstrap milestone queries a table, so there is
 * nothing to type yet. Replace this interface wholesale when `db:types` is wired up —
 * do not hand-write table types here.
 */
// eslint-disable-next-line @typescript-eslint/no-empty-object-type -- intentional placeholder until kysely-codegen generates the real Database interface in M1
export interface Database {}

export function createDb(env: Pick<Env, 'DATABASE_URL' | 'DB_POOL_MAX'>): Kysely<Database> {
  const pool = new pg.Pool({
    connectionString: env.DATABASE_URL,
    max: env.DB_POOL_MAX,
  });

  return new Kysely<Database>({
    dialect: new PostgresDialect({ pool }),
  });
}

/** Used by GET /ready — confirms the pooler connection actually answers a query. */
export async function pingDb(db: Kysely<Database>): Promise<boolean> {
  try {
    await db.selectNoFrom((eb) => eb.val(1).as('ok')).execute();
    return true;
  } catch {
    return false;
  }
}
